/* KORUK ASİSTAN — TEK MERKEZİ DESIGN SYSTEM
   Android / iOS / web aynı responsive çekirdeği kullanır. */
 /* ═══════════════════════════════════════════════════════════════════════════════
   KORUK ASİSTAN — TEMA MERKEZİ  (tek yetkili tanım)
   Uygulamadaki her renk / yüzey / metin / gölge / ölçü bu bloktan gelir.
   • 1) :root — iki temada ortak sabitler ve türev (var) tanımlar
   • 2) :root (açık palet) ve html[data-theme="dark"] (koyu palet) — yalnızca temaya göre
        değişen değerler; iki blok aynı sırada tutulur, yan yana okunabilir.
   Başka hiçbir yerde html düzeyinde değişken tanımlanmaz. Yeni renk gerekiyorsa buraya ekle.
   ═══════════════════════════════════════════════════════════════════════════════ */
:root{
  color-scheme:light;
  /* ── ÖLÇÜLER · TİPOGRAFİ · HAREKET ── */
  --ka-avatar-size:42px;
  --ka-profile-avatar-size:44px;
  --ka-profile-avatar-compact-size:34px;
  /* ── PROFİL FOTOĞRAFI · ROZETLİ (başlık, açılan kart, profil sayfası, web yan menüsü, kırpma ekranı tek kaynaktan) ──
     İnce altın halka + dış hare; kart ve profil sayfasında altında unvan rozeti. Boyut ve renk yalnız buradan değişir. */
  --ka-avatar-ring-w:1.5px;                                       /* ince halka kalınlığı */
  --ka-avatar-ring:rgba(var(--t-accent-rgb),.6);                  /* halka rengi */
  --ka-avatar-halo:rgba(var(--t-accent-rgb),.1);                  /* dış hare rengi */
  --ka-avatar-halo-w:4px;                                         /* hare genişliği (küçük/orta boyut) */
  --ka-avatar-halo-w-lg:7px;                                      /* hare genişliği (profil sayfası boyutu) */
  --ka-avatar-ring-shadow:0 0 0 var(--ka-avatar-ring-w) var(--ka-avatar-ring),0 0 0 calc(var(--ka-avatar-ring-w) + var(--ka-avatar-halo-w)) var(--ka-avatar-halo);
  --ka-avatar-ring-shadow-lg:0 0 0 var(--ka-avatar-ring-w) var(--ka-avatar-ring),0 0 0 calc(var(--ka-avatar-ring-w) + var(--ka-avatar-halo-w-lg)) var(--ka-avatar-halo);
  --ka-avatar-gap:var(--ka-card-raised-bg);                       /* rozetin çevresindeki boşluk = üstünde durduğu yüzey */
  --ka-avatar-chip-bg:var(--ka-btn-primary-bg);                   /* rozet = birincil düğmeyle aynı "altın cam" */
  --ka-avatar-chip-ink:var(--ka-btn-primary-ink);
  --ka-avatar-chip-shadow:0 3px 8px rgba(var(--t-accent-rgb),.35);
  --ka-avatar-chip-max:132px;                                     /* rozet en fazla bu kadar geniş (uzun unvan kısaltılır) */
  --ka-avatar-chip-max-sm:84px;                                   /* açılan kart ve önizlemedeki küçük avatarın rozet sınırı */
  --ka-photo-crop-w:420px;                                        /* kırpma penceresi genişliği */
  --ka-photo-crop-stage:320px;                                    /* kırpma sahnesinin en büyük kenarı */
  --ka-photo-crop-dim:rgba(var(--k-black),.55);                   /* kadrajın (daire) dışını karartma rengi */
  --ka-photo-crop-reach:100vmax;                                  /* karartmanın sahneyi tamamen kaplaması için yayılım */
  --ka-font:Inter,Manrope,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  --ka-font-mono:"JetBrains Mono",Consolas,monospace;
  --ka-font-size-xs:var(--ka-fs-11);
  --ka-font-size-sm:var(--ka-fs-13);
  --ka-font-size-md:var(--ka-fs-15);
  --ka-font-size-lg:var(--ka-fs-18);
  --ka-font-size-xl:var(--ka-fs-22);
  --ka-font-size-2xl:var(--ka-fs-28);
  --ka-line-height:calc(1.5 * var(--ka-lh-k));
  --ka-space-1:var(--ka-sp-4);
  --ka-space-2:var(--ka-sp-8);
  --ka-space-3:var(--ka-sp-12);
  --ka-space-4:var(--ka-sp-16);
  --ka-space-5:var(--ka-sp-20);
  --ka-space-6:var(--ka-sp-24);
  --ka-space-8:var(--ka-sp-32);
  --ka-control-height-sm:36px;
  --ka-control-height:44px;
  --ka-control-height-lg:50px;
  --ka-header-height:64px;
  --ka-bottom-nav-height:72px;
  --ka-content-max-width:1180px;
  /* ── WEB ARAYÜZÜ (≥1100px: sol menü + üst çubuk + geniş ana sayfa) — "WEB ARAYÜZÜ" bölümü yalnız bunları kullanır ── */
  --ka-web-side-w:clamp(240px,calc(240px + (100vw - 1100px) * .27),288px);   /* sol menü genişliği: 1100px'te 240px → 1280px'ten itibaren 288px */
  --ka-web-top-h:68px;                     /* üst çubuk yüksekliği */
  --ka-web-page-max:1560px;                /* içerik alanı üst sınırı */
  --ka-web-gutter:clamp(24px,calc(24px + (100vw - 1100px) * .045),32px);      /* içerik yan boşluğu: 24px → 32px */
  --ka-web-gap:var(--ka-sp-20);            /* kartlar arası boşluk */
  --ka-web-aside-w:352px;                  /* ana sayfa sağ sütunu (yalnız ≥1280px) */
  --ka-web-row:4px;                        /* ana sayfa ızgarası satır birimi (web-shell.js bu değeri okur) */
  --ka-web-hero-card:clamp(420px,calc(420px + (100vw - 1100px) * .56),520px); /* karşılama kartında canlı ders kartı genişliği: 420px → 520px */
  --ka-safe-top:env(safe-area-inset-top,0px);
  --ka-safe-right:env(safe-area-inset-right,0px);
  --ka-safe-bottom:env(safe-area-inset-bottom,0px);
  --ka-safe-left:env(safe-area-inset-left,0px);
  --ka-radius-sm:var(--ka-r-1);
  --ka-radius-md:var(--ka-r-3);
  --ka-radius-lg:var(--ka-r-6);
  --ka-radius-xl:var(--ka-r-8);
  --ka-radius-pill:999px;
  --ka-transition-fast:var(--ka-dur-120) ease;
  --ka-transition:var(--ka-dur-180) ease;

  /* ── KÖŞE ÖLÇEĞİ — tüm köşeler tek değerden türer: --ka-radius-base (0 = köşeli, 20 = çok yuvarlak) ── */
  --ka-radius-base:14px;
  --ka-r-1:max(0px,calc(var(--ka-radius-base) - 6px));    /* 8  */
  --ka-r-2:max(0px,calc(var(--ka-radius-base) - 4px));    /* 10 */
  --ka-r-3:max(0px,calc(var(--ka-radius-base) - 2px));    /* 12 */
  --ka-r-4:var(--ka-radius-base);                          /* 14 */
  --ka-r-5:calc(var(--ka-radius-base) + 2px);              /* 16 */
  --ka-r-6:calc(var(--ka-radius-base) + 4px);              /* 18 */
  --ka-r-7:calc(var(--ka-radius-base) + 6px);              /* 20 */
  --ka-r-8:calc(var(--ka-radius-base) + 8px);              /* 22 */
  --ka-r-9:calc(var(--ka-radius-base) + 10px);             /* 24 */
  --ka-r-10:calc(var(--ka-radius-base) + 14px);            /* 28 */

  /* ── ÇİZGİ · HALKA · BULANIKLIK ── */
  --ka-border-w:1px;                     /* tüm kart/kutu/buton çizgi kalınlığı */
  --ka-ring-w:3px;                       /* odak halkası kalınlığı */
  --ka-ring-offset:2px;                    /* odak halkasının nesneden uzaklığı */
  --ka-blur-k:1;                         /* bulanıklık çarpanı (1 = olduğu gibi, 0 = bulanıklık yok, 1.5 = daha buzlu) */

  /* ── BUTON — tüm .ka-btn çeşitleri ve düğme benzeri öğeler ── */
  --ka-btn-radius:var(--ka-r-3);         /* orta düğme köşesi */
  --ka-btn-radius-sm:var(--ka-r-2);      /* küçük düğme köşesi */
  --ka-btn-radius-lg:var(--ka-r-5);      /* büyük düğme köşesi */
  --ka-btn-grow:0px;                     /* tüm düğme yüksekliklerine eklenir (+4px = daha iri, -4px = sıkışık) */
  --ka-btn-h-sm:calc(var(--ka-control-height-sm) + var(--ka-btn-grow));
  --ka-btn-h-md:calc(var(--ka-control-height) + var(--ka-btn-grow));
  --ka-btn-h-lg:calc(var(--ka-control-height-lg) + var(--ka-btn-grow));
  --ka-btn-px:var(--ka-space-4);         /* yatay iç boşluk (orta) */
  --ka-btn-px-sm:var(--ka-space-3);
  --ka-btn-px-lg:var(--ka-space-5);
  --ka-btn-gap:var(--ka-space-2);        /* ikon ile yazı arası */
  --ka-btn-weight:750;
  --ka-btn-tracking:-.01em;
  --ka-btn-border-w:var(--ka-border-w);
  --ka-btn-danger-bg:var(--ka-danger);
  --ka-btn-danger-text:var(--ka-danger-text);
  --ka-btn-ghost-bg:transparent;
  --ka-btn-ghost-hover:var(--ka-muted-bg);
  --ka-btn-ghost-text:var(--ka-text);

  /* ── FORM KUTUSU — input / select / textarea / .ka-input ── */
  --ka-field-radius:var(--ka-r-4);
  --ka-field-radius-sm:var(--ka-r-2);
  --ka-field-grow:0px;                   /* tüm form kutusu yüksekliklerine eklenir */
  --ka-field-h-md:calc(var(--ka-control-height) + var(--ka-field-grow));
  --ka-field-px:var(--ka-sp-12);
  --ka-field-py:var(--ka-sp-9);
  --ka-field-border-w:var(--ka-border-w);
  --ka-field-textarea-h:96px;
  --ka-field-ring:0 0 0 var(--ka-ring-w) var(--ka-focus);   /* odaktaki halka */

  /* ── KART ── */
  --ka-card-radius:var(--ka-r-6);        /* standart kart */
  --ka-card-radius-sm:var(--ka-r-4);     /* iç kutu / satır kartı */
  --ka-card-radius-lg:var(--ka-r-7);     /* büyük kart */
  --ka-card-pad:var(--ka-space-4);
  --ka-card-border-w:var(--ka-border-w);

  /* ── KAPAK (hero / sayfa başlığı kartları) ── */
  --ka-cover-radius:var(--ka-r-8);
  --ka-cover-radius-sm:var(--ka-r-6);
  --ka-cover-radius-lg:var(--ka-r-10);

  /* ── SAYFA BAŞLIĞI — her sayfanın geri düğmesinin altındaki başlık kartı (hepsi bu değerlerle çizilir) ── */
  --ka-ph-bg:radial-gradient(120% 100% at 100% 0%,rgba(var(--t-accent-rgb),.11),transparent 58%),var(--ka-card-bg);  /* kart zemini; düz başlık için: transparent */
  --ka-ph-border-w:var(--ka-border-w);   /* çerçeve kalınlığı (0 = çerçevesiz) */
  --ka-ph-border:var(--gl-edge);         /* çerçeve rengi */
  --ka-ph-radius:var(--ka-cover-radius); /* köşe */
  --ka-ph-shadow:var(--gl-shadow);       /* gölge (none = düz) */
  --ka-ph-blur:var(--gl-blur);           /* cam bulanıklığı */
  --ka-ph-pad-y:var(--ka-sp-14);         /* iç boşluk: üst-alt */
  --ka-ph-pad-x:var(--ka-sp-16);         /* iç boşluk: sağ-sol */
  --ka-ph-gap:var(--ka-sp-12);           /* başlık ile eylem/rozet arası */
  --ka-ph-min-h:0px;                     /* en az yükseklik (ör. 120px = daha kapak gibi) */
  --ka-ph-bar-pad-y:var(--ka-sp-6);       /* çubuk başlık (detay sayfası üst çubuğu): iç boşluk üst-alt */
  --ka-ph-bar-pad-x:var(--ka-sp-8);       /* çubuk başlık: iç boşluk sağ-sol */
  --ka-ph-bar-title-size:var(--ka-fs-17); /* çubuk başlık yazı boyutu */
  --ka-ph-title:var(--gl-fg);            /* başlık rengi */
  --ka-ph-title-size:var(--ka-fs-22);
  --ka-ph-title-weight:var(--ka-fw-800);
  --ka-ph-title-tracking:var(--ka-ls-n02);
  --ka-ph-title-lh:var(--ka-lh-1-2);
  --ka-ph-sub:var(--gl-sub);             /* açıklama rengi */
  --ka-ph-sub-size:var(--ka-fs-13);
  --ka-ph-sub-lh:var(--ka-lh-1-35);
  --ka-ph-kicker:var(--hd-chip);         /* başlık üstü küçük etiket (ör. ÖĞRENCİ MERKEZİ) */
  --ka-ph-kicker-size:var(--ka-fs-10);
  --ka-ph-kicker-tracking:var(--ka-ls-12);
  --ka-ph-icon-bg:linear-gradient(135deg,rgba(var(--t-gold-hi-rgb),.30),rgba(var(--t-gold-lo-rgb),.12));  /* başlık ikon kutusu */
  --ka-ph-icon-fg:var(--hd-chip);
  --ka-ph-icon-border:rgba(var(--t-accent-rgb),.34);
  --ka-ph-icon-radius:var(--ka-cover-radius-sm);
  --ka-ph-icon-shadow:0 var(--ka-sh-6) var(--ka-sh-18) rgba(var(--t-gold-lo-rgb),calc(.14 * var(--ka-shadow-a)));
  --ka-ph-icon-size:46px;                /* genel .ka-page-head__icon kutusunun boyutu */
  --ka-ph-deco:none;                     /* sayfaların kendi süs şekilleri/emojileri: none = kapalı, block = açık */

  /* ── PENCERE · ALT SAYFA · AÇILIR MENÜ ── */
  --ka-sheet-radius:var(--ka-r-6);       /* ortadaki pencere */
  --ka-sheet-radius-lg:var(--ka-r-9);    /* alttan açılan sayfa / büyük pencere */
  --ka-sheet-pad:var(--ka-space-4);

  /* ── YAPIŞKAN ŞERİTLER — kaydırırken içeriğin üstünde kalan şerit / başlık / tablo sütunu. Saydam olursa alttan kayan yazılar üst üste biner; bu yüzden hepsi bu opak zemini kullanır ── */
  --ka-sticky-bg:var(--pp-solid);                 /* opak zemin (şeritler) */
  --ka-sticky-cell-bg:color-mix(in srgb,var(--gl-fg) 6%,var(--ka-sticky-bg));  /* opak, hafif tonlu zemin (yapışkan tablo başlığı / ilk sütun / sekme şeridi) */

  /* ── ANA SAYFA · HAFTALIK NÖBET — her gün kendi renginde: gün adı yazısı + gün bölümü zemini + soldaki çubuk ── */
  --ka-wd-1:var(--c-indigo);                      /* Pazartesi — RGB üçlüsü (KATEGORİ PALETİ'nden bir renk seçin) */
  --ka-wd-2:var(--c-amber);                       /* Salı */
  --ka-wd-3:var(--c-rose);                        /* Çarşamba */
  --ka-wd-4:var(--c-cyan);                        /* Perşembe */
  --ka-wd-5:var(--c-violet);                      /* Cuma */
  --ka-wd-bg-a:.12;                               /* gün bölümü zemini: üstte (0 = zemin yok) */
  --ka-wd-bg-a-end:.03;                           /* gün bölümü zemini: altta */
  --ka-wd-bg-a-today:.24;                         /* bugünün bölümü: üstte, daha belirgin */
  --ka-wd-bar-w:var(--ka-sp-4);                   /* soldaki renk çubuğu kalınlığı (0 = çubuksuz) */
  --ka-wd-ink-mix:54%;                            /* gün adı yazısı: gün renginin oranı (kalanı metin rengi; okunurluk için) */

  /* ── ALT MENÜ (alt navigasyon çubuğu) — kutusuz ikonlar, seçili sekmede renkli kapsül, her sekmenin kendi rengi.
        Çubuğun zemini/yazısı/çizgisi/gölgesi ve menü düğmesi halkası açık-koyu paletlerde: --ka-nav-bg, -text, -border, -shadow, -menu-ring ── */
  --ka-nav-tab-1:var(--t-accent-rgb);             /* 1. sekme (Bugün / Özet) — RGB üçlüsü (marka rengini izler) */
  --ka-nav-tab-2:var(--c-sky);                    /* 2. sekme (Programım / Okul) — KATEGORİ PALETİ'nden bir renk */
  --ka-nav-tab-3:var(--c-violet);                 /* 4. sekme (Okul / İletişim) */
  --ka-nav-tab-4:var(--c-emerald);                /* 5. sekme (Ben) */
  --ka-nav-radius:var(--ka-r-8);                  /* çubuğun üst köşeleri (geniş ekranda yüzen çubuk için --ka-r-10) */
  --ka-nav-blur:26px;                             /* cam bulanıklığı */
  --ka-nav-label-size:var(--ka-fs-10);            /* sekme yazısı */
  --ka-nav-pill-w:52px;                           /* seçili sekmenin kapsül genişliği */
  --ka-nav-pill-a:.18;                            /* kapsül zemin yoğunluğu (0 = kapsülsüz) */
  --ka-nav-pill-edge-a:.34;                       /* kapsül çizgisi yoğunluğu */
  --ka-nav-pill-glow-a:.26;                       /* kapsül ışıması (0 = ışımasız) */
  --ka-nav-ink-mix:44%;                           /* seçili sekmenin yazı/ikon rengi: sekme renginin oranı (kalanı metin rengi) */

  /* ── BİRİNCİL DÜĞME (ALTIN CAM) — uygulamadaki tüm sarı "ana eylem" düğmeleri tek cam malzemeden: genel .ka-btn ("+ Öğretmen", "Yeni Plan Tanımı",
        "Şimdi Senkronize Et"…), yüzen ↑ düğmesi, alt menü orta düğmesi, seçili (altın) durumlar. Cam yoğunluğu, yazı, çizgi, gölge ve odak halkası
        açık-koyu paletlerde: --ka-btn-primary-gloss-a, -tint-hi-a, -tint-lo-a, -smoke-a, -ink, -ink-shadow, -edge, -shadow, -ring ── */
  --ka-btn-primary-blur:18px;                     /* cam bulanıklığı (--ka-blur-k ile ölçeklenir; 0 = bulanıksız, zayıf cihazlarda önerilir) */
  --ka-btn-primary-sat:1.7;                       /* camın arkasındaki rengin doygunluğu */
  --ka-btn-primary-smoke-rgb:12,12,24;            /* camın altındaki "dumanlı" katmanın rengi (yoğunluğu palette: -smoke-a) */
  --ka-btn-primary-hover-boost:.10;               /* üzerine gelince cam rengine eklenen yoğunluk */
  --ka-btn-primary-press-scale:.97;               /* basılınca küçülme (1 = küçülmez) */
  --ka-btn-primary-press-dim:.88;                 /* basılınca kararma (1 = kararmaz) */
  --ka-btn-primary-disabled-a:.45;                /* pasif düğmenin opaklığı */
  --ka-btn-primary-disabled-sat:.6;               /* pasif düğmenin renk canlılığı */
  --ka-btn-primary-filter:blur(calc(var(--ka-btn-primary-blur) * var(--ka-blur-k))) saturate(var(--ka-btn-primary-sat));
  --ka-btn-primary-bg:linear-gradient(180deg,rgba(var(--k-white),var(--ka-btn-primary-gloss-a)),rgba(var(--k-white),0) 55%),linear-gradient(135deg,rgba(var(--t-gold-hi-rgb),var(--ka-btn-primary-tint-hi-a)),rgba(var(--t-gold-lo-rgb),var(--ka-btn-primary-tint-lo-a))),linear-gradient(rgba(var(--ka-btn-primary-smoke-rgb),var(--ka-btn-primary-smoke-a)),rgba(var(--ka-btn-primary-smoke-rgb),var(--ka-btn-primary-smoke-a)));
  --ka-btn-primary-bg-hover:linear-gradient(180deg,rgba(var(--k-white),var(--ka-btn-primary-gloss-a)),rgba(var(--k-white),0) 55%),linear-gradient(135deg,rgba(var(--t-gold-hover-hi-rgb),calc(var(--ka-btn-primary-tint-hi-a) + var(--ka-btn-primary-hover-boost))),rgba(var(--t-gold-hover-lo-rgb),calc(var(--ka-btn-primary-tint-lo-a) + var(--ka-btn-primary-hover-boost)))),linear-gradient(rgba(var(--ka-btn-primary-smoke-rgb),var(--ka-btn-primary-smoke-a)),rgba(var(--ka-btn-primary-smoke-rgb),var(--ka-btn-primary-smoke-a)));

  /* ── HAVA DURUMU (GÖKYÜZÜ CAMI) — ana sayfa hava kartı + tıklayınca açılan detay penceresi tek gökyüzü motorunu paylaşır.
        Gökyüzü 7 durum × gündüz/gece: her birinin üst (-1) / alt (-2) rengi, bulut rengi (-cloud) ve bulut yoğunluğu (-co) aşağıda.
        Yazı her gökyüzünde beyazdır; okunabilirliği "duman" katmanı (--ka-wx-smoke-*) ve cam çipler (--ka-wx-chip*) sağlar.
        --ka-wx-speed animasyon hızını ölçer (1 = normal, 2 = yarı hız, 0 = durağan); --ka-wx-t-* tek tek süreleri belirler ── */
  --ka-wx-speed:1;
  --ka-wx-sun-day-1:#1b5fd1;   --ka-wx-sun-day-2:#4a98e2;   --ka-wx-sun-day-cloud:#ffffff;   --ka-wx-sun-day-co:.5;
  --ka-wx-sun-night-1:#0b1230; --ka-wx-sun-night-2:#26346e; --ka-wx-sun-night-cloud:#b9c3f0; --ka-wx-sun-night-co:.28;
  --ka-wx-pc-day-1:#2a64c0;    --ka-wx-pc-day-2:#5f95d6;    --ka-wx-pc-day-cloud:#ffffff;    --ka-wx-pc-day-co:.85;
  --ka-wx-pc-night-1:#111a3c;  --ka-wx-pc-night-2:#34416f;  --ka-wx-pc-night-cloud:#b9c3f0;  --ka-wx-pc-night-co:.30;
  --ka-wx-cloud-day-1:#456389; --ka-wx-cloud-day-2:#6f87a6; --ka-wx-cloud-day-cloud:#e6edf6; --ka-wx-cloud-day-co:.6;
  --ka-wx-cloud-night-1:#161b2e; --ka-wx-cloud-night-2:#323a55; --ka-wx-cloud-night-cloud:#9aa6d4; --ka-wx-cloud-night-co:.32;
  --ka-wx-rain-day-1:#2f4660;  --ka-wx-rain-day-2:#587390;  --ka-wx-rain-day-cloud:#aebccc;  --ka-wx-rain-day-co:.55;
