/* ===== DASHBOARD SCHOOL SUMMARY REFERENCE ===== */
.ka-school-summary-section{background:transparent!important;border:0!important;box-shadow:none!important;padding:0!important}

/* Glassmorphism sahne */
.ka-school-summary-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--ka-sp-9);padding:var(--ka-sp-10);border-radius:var(--ka-r-9);
  background:
    radial-gradient(ellipse 80% 60% at 15% 25%,rgba(var(--c-indigo),.55) 0%,transparent 65%),
    radial-gradient(ellipse 70% 55% at 85% 75%,rgba(var(--c-emerald),.50) 0%,transparent 60%),
    radial-gradient(ellipse 65% 60% at 60% 5%,rgba(var(--c-amber),.45) 0%,transparent 55%),
    linear-gradient(135deg,rgb(var(--k-blue-c7d9ff)) 0%,rgb(var(--k-green-bbf5e0)) 50%,rgb(var(--k-amber-fde68a)) 100%)}
/* Frosted cam kartlar */
