.ka-wx-moon{right:44px;top:42px;width:46px;height:46px;border-radius:50%;box-shadow:inset -14px 4px 0 0 var(--ka-wx-moon),0 0 var(--ka-sh-34) var(--ka-sh-4) var(--ka-wx-moon-glow);transform:rotate(-10deg);animation:ka-wx-moonfloat var(--ka-wx-t-moon) ease-in-out infinite}
.ka-wx-stars{inset:0}
.ka-wx-stars i{position:absolute;width:2px;height:2px;border-radius:50%;background:var(--ka-wx-star);box-shadow:0 0 var(--ka-sh-5) var(--ka-sh-1) var(--ka-wx-star-glow);animation:ka-wx-twinkle var(--ka-wx-t-star) ease-in-out infinite;animation-delay:calc(var(--ka-wx-t-star) * var(--d,0) * -1)}
.ka-wx-stars i:nth-child(1){left:52%;top:12%}
.ka-wx-stars i:nth-child(2){left:64%;top:26%;--d:.31}
.ka-wx-stars i:nth-child(3){left:78%;top:10%;--d:.62}
.ka-wx-stars i:nth-child(4){left:90%;top:30%;--d:.16}
.ka-wx-stars i:nth-child(5){left:58%;top:62%;--d:.5}
.ka-wx-stars i:nth-child(6){left:84%;top:58%;--d:.75}
.ka-wx-stars i:nth-child(7){left:70%;top:76%;--d:.25}
.ka-wx-clouds{top:0;right:0;bottom:0;width:64%;overflow:hidden;container-type:inline-size;-webkit-mask:linear-gradient(90deg,transparent,rgb(var(--k-black)) 24%);mask:linear-gradient(90deg,transparent,rgb(var(--k-black)) 24%)}
.ka-wx-cld{position:absolute;left:0;display:none;width:92px;height:28px;border-radius:var(--ka-radius-pill);background:var(--wx-cloud);opacity:var(--wx-co);animation:ka-wx-drift var(--ka-wx-t-cloud-1) linear infinite;animation-delay:calc(var(--ka-wx-t-cloud-1) * var(--d,0) * -1)}
.ka-wx-cld::before,.ka-wx-cld::after{content:"";position:absolute;border-radius:50%;background:var(--wx-cloud)}
.ka-wx-cld::before{width:42px;height:42px;left:12px;top:-19px}
.ka-wx-cld::after{width:32px;height:32px;left:44px;top:-12px}
.ka-wx-c1{top:62px;--d:.32}
.ka-wx-c2{top:104px;scale:1.25;animation-duration:var(--ka-wx-t-cloud-2);--d:.69}
.ka-wx-c3{top:144px;scale:.85;animation-duration:var(--ka-wx-t-cloud-3);--d:.14}
.ka-wx-rain,.ka-wx-snow,.ka-wx-fog{inset:0;overflow:hidden;container-type:size}
.ka-wx-rain i{position:absolute;top:-24px;width:1.5px;height:18px;border-radius:var(--ka-radius-pill);background:linear-gradient(180deg,var(--ka-wx-rain-0),var(--ka-wx-rain-1));animation:ka-wx-drop var(--ka-wx-t-rain) linear infinite;animation-delay:calc(var(--ka-wx-t-rain) * var(--d,0) * -1)}
.ka-wx-rain i:nth-child(3n){animation-duration:var(--ka-wx-t-rain-fast);height:22px}
.ka-wx-rain i:nth-child(3n+1){animation-duration:var(--ka-wx-t-rain-slow);opacity:.6}
.ka-wx.k-storm .ka-wx-rain i{animation-duration:var(--ka-wx-t-storm)}
.ka-wx-rain i:nth-child(1){left:3%;--d:.125}
.ka-wx-rain i:nth-child(2){left:10%;--d:.625}
.ka-wx-rain i:nth-child(3){left:17%;--d:.375}
.ka-wx-rain i:nth-child(4){left:25%;--d:.875}
.ka-wx-rain i:nth-child(5){left:33%;--d:.25}
.ka-wx-rain i:nth-child(6){left:41%;--d:.75}
.ka-wx-rain i:nth-child(7){left:49%;--d:.5}
.ka-wx-rain i:nth-child(8){left:57%;--d:1}
.ka-wx-rain i:nth-child(9){left:65%;--d:.19}
.ka-wx-rain i:nth-child(10){left:73%;--d:.69}
.ka-wx-rain i:nth-child(11){left:81%;--d:.44}
.ka-wx-rain i:nth-child(12){left:89%;--d:.94}
.ka-wx-rain i:nth-child(13){left:95%;--d:.31}
.ka-wx-rain i:nth-child(14){left:46%;--d:.81}
.ka-wx-snow i{position:absolute;top:-8px;width:4px;height:4px;border-radius:50%;background:var(--ka-wx-flake);opacity:.9;box-shadow:0 0 var(--ka-sh-4) var(--ka-wx-flake-glow);animation:ka-wx-flake var(--ka-wx-t-snow) linear infinite;animation-delay:calc(var(--ka-wx-t-snow) * var(--d,0) * -1)}
.ka-wx-snow i:nth-child(odd){width:3px;height:3px;opacity:.7;animation-duration:var(--ka-wx-t-snow-slow)}
.ka-wx-snow i:nth-child(1){left:5%;--d:.12}
.ka-wx-snow i:nth-child(2){left:13%;--d:.5}
.ka-wx-snow i:nth-child(3){left:22%;--d:.88}
.ka-wx-snow i:nth-child(4){left:31%;--d:.25}
.ka-wx-snow i:nth-child(5){left:40%;--d:.62}
.ka-wx-snow i:nth-child(6){left:49%;--d:1}
.ka-wx-snow i:nth-child(7){left:58%;--d:.38}
.ka-wx-snow i:nth-child(8){left:67%;--d:.75}
.ka-wx-snow i:nth-child(9){left:76%;--d:.06}
.ka-wx-snow i:nth-child(10){left:85%;--d:.56}
.ka-wx-snow i:nth-child(11){left:93%;--d:.94}
.ka-wx-snow i:nth-child(12){left:37%;--d:1.12}
.ka-wx-fog i{position:absolute;left:-30%;width:160%;height:46px;border-radius:50%;background:radial-gradient(ellipse at center,var(--ka-wx-mist-1),var(--ka-wx-mist-0) 70%);animation:ka-wx-mist var(--ka-wx-t-mist-1) ease-in-out infinite alternate}
.ka-wx-fog i:nth-child(1){top:22%}
.ka-wx-fog i:nth-child(2){top:60%;animation-duration:var(--ka-wx-t-mist-2);animation-direction:alternate-reverse}
.ka-wx-fog i:nth-child(3){top:84%}
.ka-wx-bolt{inset:0;opacity:0;background:radial-gradient(170px 120px at 78% 22%,var(--ka-wx-bolt-1),var(--ka-wx-bolt-2) 55%,var(--ka-wx-bolt-3) 80%);animation:ka-wx-flash var(--ka-wx-t-bolt) linear infinite}
/* hangi durumda hangi öğe görünür */
.ka-wx.k-sun.is-day .ka-wx-sun,.ka-wx.k-pc.is-day .ka-wx-sun{display:block}
.ka-wx.k-sun.is-night .ka-wx-moon,.ka-wx.k-pc.is-night .ka-wx-moon,.ka-wx.k-cloud.is-night .ka-wx-moon{display:block}
.ka-wx.k-cloud.is-night .ka-wx-moon{opacity:.45}
.ka-wx.k-sun.is-night .ka-wx-stars,.ka-wx.k-pc.is-night .ka-wx-stars,.ka-wx.k-cloud.is-night .ka-wx-stars{display:block}
.ka-wx.k-cloud.is-night .ka-wx-stars{opacity:.5}
.ka-wx.k-sun .ka-wx-clouds,.ka-wx.k-pc .ka-wx-clouds,.ka-wx.k-cloud .ka-wx-clouds,.ka-wx.k-rain .ka-wx-clouds,.ka-wx.k-storm .ka-wx-clouds,.ka-wx.k-snow .ka-wx-clouds{display:block}
.ka-wx.k-sun .ka-wx-c1,.ka-wx.k-pc .ka-wx-c1,.ka-wx.k-pc .ka-wx-c2,.ka-wx.k-cloud .ka-wx-cld,.ka-wx.k-rain .ka-wx-cld,.ka-wx.k-storm .ka-wx-cld,.ka-wx.k-snow .ka-wx-c1,.ka-wx.k-snow .ka-wx-c2{display:block}
.ka-wx.k-rain .ka-wx-rain,.ka-wx.k-storm .ka-wx-rain,.ka-wx.k-snow .ka-wx-snow,.ka-wx.k-fog .ka-wx-fog,.ka-wx.k-storm .ka-wx-bolt{display:block}
@keyframes ka-wx-sunpulse{50%{box-shadow:0 0 var(--ka-sh-50) var(--ka-sh-18) var(--ka-wx-sun-glow-hi)}}
@keyframes ka-wx-spin{to{transform:rotate(360deg)}}
@keyframes ka-wx-moonfloat{50%{transform:rotate(-10deg) translateY(-3px)}}
@keyframes ka-wx-twinkle{0%,100%{opacity:.25}50%{opacity:1}}
@keyframes ka-wx-drift{from{transform:translateX(-130px)}to{transform:translateX(100cqw)}}
@keyframes ka-wx-drop{from{transform:translate(0,-24px) rotate(13deg)}to{transform:translate(-75px,calc(100cqh + 24px)) rotate(13deg)}}
@keyframes ka-wx-flake{0%{transform:translate(0,-10px)}33%{transform:translate(9px,33cqh)}66%{transform:translate(-7px,66cqh)}100%{transform:translate(4px,calc(100cqh + 10px))}}
@keyframes ka-wx-mist{from{transform:translateX(-8%)}to{transform:translateX(8%)}}
@keyframes ka-wx-flash{0%,88%,100%{opacity:0}89%{opacity:.9}90.5%{opacity:.08}92%{opacity:.7}95%{opacity:0}}
@keyframes ka-wx-rise{from{opacity:0;transform:translateY(16px) scale(.98)}}
.ka-wx.is-paused .ka-wx-sky *,.ka-wx.is-paused .ka-wx-sky *::before{animation-play-state:paused!important}

/* — cam çipler: konum, ölçüm kutuları, saatlik kutular, kapat düğmesi — */
.ka-wx-loc,.ka-wx-go,.ka-wx-s,.ka-wx-pill,.ka-wx-hr,.ka-wx-day{background:var(--ka-wx-chip);border:var(--ka-border-w) solid var(--ka-wx-chip-edge);-webkit-backdrop-filter:blur(calc(var(--ka-wx-chip-blur) * var(--ka-blur-k)));backdrop-filter:blur(calc(var(--ka-wx-chip-blur) * var(--ka-blur-k)))}
.ka-wx-loc{display:inline-flex;align-items:center;gap:var(--ka-sp-6);min-width:0;max-width:calc(100% - 44px);height:28px;padding:0 var(--ka-sp-11) 0 var(--ka-sp-9);border-radius:var(--ka-radius-pill);font-size:var(--ka-fs-11);font-weight:var(--ka-fw-700);line-height:1}
.ka-wx-loc svg{flex:none}
.ka-wx-loc>span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.ka-wx-go{appearance:none;flex:none;width:34px;height:34px;padding:0;border-radius:var(--ka-r-3);display:grid;place-items:center;color:inherit;font:inherit;cursor:pointer}
.ka-wx-pill{display:inline-flex;align-items:center;gap:var(--ka-sp-5);height:26px;padding:0 var(--ka-sp-10);border-radius:var(--ka-radius-pill);font-size:var(--ka-fs-11-5);font-weight:var(--ka-fw-700);line-height:1;white-space:nowrap}
.ka-wx-s{box-sizing:border-box;display:flex;align-items:center;gap:var(--ka-sp-8);min-width:0;padding:var(--ka-sp-8) var(--ka-sp-10);border-radius:var(--ka-r-4)}
.ka-wx-s>svg{flex:none;opacity:.92}
.ka-wx-s>span{min-width:0}
.ka-wx-s small{display:block;font-size:var(--ka-fs-9-5);font-weight:var(--ka-fw-700);letter-spacing:var(--ka-ls-06);line-height:var(--ka-lh-1-2);color:var(--ka-wx-ink-2);text-transform:uppercase}
.ka-wx-s b{display:block;margin-top:var(--ka-sp-1);font-size:var(--ka-fs-14);font-weight:var(--ka-fw-800);line-height:var(--ka-lh-1-2);white-space:nowrap}
.ka-wx-s b em{margin-left:var(--ka-sp-3);font-style:normal;font-size:var(--ka-fs-9-5);font-weight:var(--ka-fw-700);opacity:.9}

/* — ana sayfa hava kartı: tek satırlık, temaya uyumlu şerit (sıcaklık · durum · konum · ok). Nem/rüzgâr/basınç yalnız detay penceresindedir. — */
html #v2ModuleRoot .ka-home #khWeather.ka-wx{
  --ka-wx-ink:var(--ka-wxc-ink);--ka-wx-ink-2:var(--ka-wxc-ink-2);--ka-wx-ink-shadow:transparent;--ka-wx-edge:var(--ka-border);
  --ka-wx-chip:var(--ka-muted-bg);--ka-wx-chip-edge:var(--ka-border);
  --wx-cloud:color-mix(in srgb,var(--wx-2) 50%,transparent);
  --ka-wx-rain-0:transparent;--ka-wx-rain-1:color-mix(in srgb,var(--ka-wxc-ink) 40%,transparent);
  --ka-wx-flake:color-mix(in srgb,var(--ka-wxc-ink) 45%,transparent);--ka-wx-flake-glow:transparent;
  --ka-wx-mist-1:color-mix(in srgb,var(--ka-wxc-ink) 12%,transparent);--ka-wx-mist-0:transparent;
  --ka-wx-moon:color-mix(in srgb,var(--wx-2) 55%,var(--ka-wxc-ink));--ka-wx-moon-glow:transparent;
  --ka-wx-star:var(--ka-wxc-ink);--ka-wx-star-glow:transparent;
  display:block;width:100%;min-height:0;padding:var(--ka-sp-10) var(--ka-sp-12) var(--ka-sp-10) var(--ka-sp-14);border-radius:var(--ka-r-6);text-align:left;cursor:pointer;font:inherit;
  background:linear-gradient(165deg,color-mix(in srgb,var(--wx-2) var(--ka-wxc-tint),transparent),color-mix(in srgb,var(--wx-1) var(--ka-wxc-tint),transparent)),var(--ka-card-bg);
  border:var(--ka-border-w) solid var(--ka-wx-edge);box-shadow:var(--ka-shadow-md);color:var(--ka-wx-ink);
  text-shadow:none;-webkit-backdrop-filter:none;backdrop-filter:none;
  transition:transform var(--ka-dur-220) var(--ka-ease-1);
}
html #v2ModuleRoot .ka-home #khWeather.ka-wx::after{content:none;display:none}
@media(hover:hover){html #v2ModuleRoot .ka-home #khWeather.ka-wx:hover{transform:translateY(-1px)}}
html #v2ModuleRoot .ka-home #khWeather.ka-wx:active{transform:scale(.995)}
html #v2ModuleRoot .ka-home #khWeather.ka-wx>:is(.kh-live-icon,.kh-live-main,.kh-weather-arrow){display:none}
/* modül tema köprüsü ([class*="card"], span, small, b … !important) kart yazılarını soluklaştırmasın: yazı rengi yalnız --ka-wx-ink / --ka-wx-ink-2 */
html[data-theme] #v2ModuleRoot .ka-home #khWeather.ka-wx:not(#_x){color:var(--ka-wx-ink)!important;border-color:var(--ka-wx-edge)!important}
html[data-theme] #v2ModuleRoot .ka-home #khWeather.ka-wx:not(#_x) :is(.ka-wx-body,.ka-wx-body :is(span,small,b,em,sup,i)){color:inherit!important}
html[data-theme] #v2ModuleRoot .ka-home #khWeather.ka-wx:not(#_x) .ka-wx-body :is(.ka-wx-f,.ka-wx-loc,.ka-wx-s small){color:var(--ka-wx-ink-2)!important}
.ka-wx-body{position:relative;display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;column-gap:var(--ka-sp-12)}
.ka-wx-t{font-size:var(--ka-fs-34);font-weight:var(--ka-fw-800);letter-spacing:var(--ka-ls-n035);line-height:1;font-variant-numeric:tabular-nums;white-space:nowrap}
.ka-wx-t sup{margin-left:var(--ka-sp-2);position:relative;top:3px;vertical-align:top;font-size:var(--ka-fs-14);font-weight:var(--ka-fw-700);letter-spacing:0;line-height:1;opacity:.8}
.ka-wx-mid{display:flex;flex-direction:column;gap:var(--ka-sp-2);min-width:0}
.ka-wx-line{display:flex;flex-wrap:wrap;align-items:baseline;gap:0 var(--ka-sp-8);min-width:0;max-height:calc(var(--ka-fs-15) * var(--ka-lh-1-2));overflow:hidden}   /* hissedilen sığmazsa ikinci satıra düşer ve gizlenir */
.ka-wx-c{flex:none;font-size:var(--ka-fs-15);font-weight:var(--ka-fw-800);letter-spacing:var(--ka-ls-n01);line-height:var(--ka-lh-1-2);white-space:nowrap}
.ka-wx-f{flex:none;white-space:nowrap;font-size:var(--ka-fs-12);font-weight:var(--ka-fw-600);color:var(--ka-wx-ink-2)}
.ka-wx-f:empty{display:none}
html #v2ModuleRoot .ka-home #khWeather .ka-wx-loc{height:auto;max-width:100%;padding:0;gap:var(--ka-sp-4);border:0;border-radius:0;background:none;-webkit-backdrop-filter:none;backdrop-filter:none;font-size:var(--ka-fs-11-5);font-weight:var(--ka-fw-600)}
html #v2ModuleRoot .ka-home #khWeather .ka-wx-go{width:28px;height:28px;-webkit-backdrop-filter:none;backdrop-filter:none}
/* kompakt kartta gökyüzü yalnız hafif bir doku: küçük güneş / ay, seyrek bulut, ince yağmur */
html #v2ModuleRoot .ka-home #khWeather.ka-wx .ka-wx-sky{opacity:var(--ka-wxc-sky-o)}
html #v2ModuleRoot .ka-home #khWeather.ka-wx .ka-wx-sun{right:6px;top:calc(50% - 22px);width:44px;height:44px;scale:.52}
html #v2ModuleRoot .ka-home #khWeather.ka-wx.k-pc.is-day .ka-wx-sun{right:34px;scale:.45}
html #v2ModuleRoot .ka-home #khWeather.ka-wx .ka-wx-moon{right:12px;top:calc(50% - 23px);scale:.7}
html #v2ModuleRoot .ka-home #khWeather.ka-wx .ka-wx-c1{top:34px;scale:.8}
html #v2ModuleRoot .ka-home #khWeather.ka-wx .ka-wx-c2{top:46px;scale:.6}
html #v2ModuleRoot .ka-home #khWeather.ka-wx .ka-wx-c3{top:28px;scale:.5}
@media(max-width:370px){
  html #v2ModuleRoot .ka-home #khWeather.ka-wx{padding:var(--ka-sp-8) var(--ka-sp-10) var(--ka-sp-8) var(--ka-sp-12)}
  .ka-wx-t{font-size:var(--ka-fs-30)}
  .ka-wx-body{column-gap:var(--ka-sp-10)}
}

/* — detay penceresi — */
.ka-wxm{position:relative;display:flex;flex-direction:column;width:min(480px,100%);max-height:min(88dvh,820px);overflow:hidden;isolation:isolate;
  border-radius:var(--ka-sheet-radius-lg);background:var(--wx-bg);border:var(--ka-border-w) solid var(--ka-wx-edge);box-shadow:var(--ka-wx-shadow-modal);
  color:var(--ka-wx-ink);text-shadow:0 var(--ka-sh-1) var(--ka-sh-8) var(--ka-wx-ink-shadow);animation:ka-wx-rise var(--ka-dur-350) var(--ka-ease-1) both}
.ka-wxm__head{flex:none;display:flex;align-items:center;justify-content:space-between;gap:var(--ka-sp-10);padding:var(--ka-sp-14) var(--ka-sp-14) 0}
.ka-wxm__scroll{flex:1 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;display:flex;flex-direction:column;gap:var(--ka-sp-16);padding:var(--ka-sp-10) var(--ka-sp-14) var(--ka-sp-16)}
.ka-wxm__hero{display:flex;flex-direction:column;align-items:flex-start;min-height:150px;padding:var(--ka-sp-6) 0 var(--ka-sp-4)}
.ka-wxm__hero>*{display:block}
.ka-wxm__t{font-size:var(--ka-fs-70);font-weight:var(--ka-fw-800);letter-spacing:var(--ka-ls-n035);line-height:1;font-variant-numeric:tabular-nums}
.ka-wxm__t sup{margin-left:var(--ka-sp-3);position:relative;top:10px;vertical-align:top;font-size:var(--ka-fs-28);font-weight:var(--ka-fw-700);letter-spacing:0;line-height:1;opacity:.85}
.ka-wxm__c{margin-top:var(--ka-sp-8);font-size:var(--ka-fs-20);font-weight:var(--ka-fw-800);letter-spacing:var(--ka-ls-n01);line-height:var(--ka-lh-1-2)}
.ka-wxm__pills{display:flex;flex-wrap:wrap;gap:var(--ka-sp-6);margin-top:var(--ka-sp-10)}
.ka-wxm__sec{display:flex;flex-direction:column;gap:var(--ka-sp-8)}
.ka-wxm__h{margin:0;font-size:var(--ka-fs-11);font-weight:var(--ka-fw-800);letter-spacing:var(--ka-ls-14);line-height:var(--ka-lh-1-2);color:var(--ka-wx-ink-2);text-transform:uppercase}
.ka-wxm__stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--ka-sp-8)}
.ka-wxm .ka-wx-s{padding:var(--ka-sp-10) var(--ka-sp-12);gap:var(--ka-sp-10)}
.ka-wxm .ka-wx-s b{font-size:var(--ka-fs-16)}
.ka-wxm__hours{display:flex;gap:var(--ka-sp-8);overflow-x:auto;padding-bottom:var(--ka-sp-4);scrollbar-width:none;overscroll-behavior-x:contain}
.ka-wxm__hours::-webkit-scrollbar{display:none}
.ka-wx-hr{flex:none;box-sizing:border-box;width:62px;display:flex;flex-direction:column;align-items:center;gap:var(--ka-sp-4);padding:var(--ka-sp-10) var(--ka-sp-4);border-radius:var(--ka-r-4)}
.ka-wx-hr small{font-size:var(--ka-fs-11);font-weight:var(--ka-fw-700);line-height:1;color:var(--ka-wx-ink-2)}
.ka-wx-hr i{font-style:normal;font-size:var(--ka-fs-22);line-height:var(--ka-lh-1-2)}
.ka-wx-hr b{font-size:var(--ka-fs-14);font-weight:var(--ka-fw-800);line-height:1}
.ka-wx-hr.is-now,.ka-wx-day.is-today{background:var(--ka-wx-chip-hi);border-color:var(--ka-wx-chip-edge-hi)}
.ka-wxm :is(.ka-wx-loc,.ka-wx-go,.ka-wx-s,.ka-wx-pill,.ka-wx-hr,.ka-wx-day){background:var(--ka-wx-panel)}
.ka-wxm :is(.ka-wx-hr.is-now,.ka-wx-day.is-today){background:var(--ka-wx-panel-hi)}
.ka-wxm .ka-wx-clouds{bottom:auto;height:var(--ka-wx-modal-sky-h)}
.ka-wxm .ka-wx-cld{opacity:calc(var(--wx-co) * var(--ka-wx-modal-cloud))}
.ka-wxm__days{display:flex;flex-direction:column;gap:var(--ka-sp-6)}
