.ka-wx-day small{display:block;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font-size:var(--ka-fs-10-5);font-weight:var(--ka-fw-600);line-height:var(--ka-lh-1-3);color:var(--ka-wx-ink-2)}
