html .ka-avatar-chip{
  position:absolute;left:50%;bottom:calc(var(--ka-sp-6) * -1);transform:translateX(-50%);z-index:3;max-width:var(--ka-avatar-chip-max);margin:0;padding:var(--ka-sp-2) var(--ka-sp-8);
  border-radius:var(--ka-chip-radius);background:var(--ka-avatar-chip-bg);color:var(--ka-avatar-chip-ink);
  font-size:var(--ka-fs-10-5);line-height:var(--ka-lh-1-25);font-weight:var(--ka-fw-850);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;pointer-events:none;
  box-shadow:var(--ka-avatar-chip-shadow),0 0 0 var(--ka-sp-2) var(--ka-avatar-gap);
}
html .ka-profile-photo{gap:var(--ka-sp-14)}
html .ka-profile-avatar-wrap .ka-avatar-chip{max-width:calc(100% + var(--ka-sp-14))}   /* uzun unvan yan sütundaki yazıya taşmaz, sığmazsa "…" ile kısalır */
