html .ka-photo-crop .ka-modal__header p{margin:var(--ka-sp-3) 0 0;font-size:var(--ka-fs-12);line-height:var(--ka-lh-1-4);color:var(--ka-text-muted)}
html .ka-photo-crop .ka-modal__body{flex:1 1 auto;min-height:0;overflow:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;display:grid;justify-items:center;gap:var(--ka-sp-10)}
