.ka-photo-crop__stage{position:relative;width:var(--pc-w);height:var(--pc-w);overflow:hidden;border-radius:var(--ka-r-5);background:var(--ka-surface-muted);touch-action:none;cursor:grab;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
