/* ═══════════ SERVİS OTURMA IZGARASI (js/modules/bus-seating-grid.js) — yalnız .bsg-root altında; renk, köşe, yazı, boşluk ve süre değerleri tema merkezi basamaklarından. Web arayüzü bölümünden ÖNCE durmalı. ═══════════ */
/* Bileşen değişkenleri: yalnız uygulama tokenlarına bağlanır (açık/koyu tema otomatik). */
.bsg-root{
  --bsg-bg:var(--ka-app-bg);--bsg-surface:var(--pp-solid);--bsg-surface-2:var(--ka-muted-bg);
  --bsg-ink:var(--ka-text);--bsg-muted:var(--ka-text-muted);
  --bsg-line:var(--ka-border);--bsg-line-strong:var(--ka-border-strong);
  --bsg-accent:var(--t-accent);--bsg-accent-ink:var(--ka-btn-primary-ink);--bsg-accent-text:var(--t-accent-text);
  --bsg-accent-soft:var(--ka-primary-soft);--bsg-accent-line:rgba(var(--t-accent-rgb),.6);
  --bsg-danger:var(--ka-danger);--bsg-danger-soft:color-mix(in srgb,var(--ka-danger) 14%,transparent);--bsg-ok:var(--ka-success);
  --bsg-bus-fill:var(--bsg-surface);--bsg-bus-edge:var(--ka-border-strong);--bsg-grid-line:var(--ka-border);
  --bsg-chip-s:60%;--bsg-chip-l:89%;--bsg-chip-ink-l:25%;
  --bsg-scrim:var(--ka-overlay);--bsg-shadow:var(--ka-shadow-modal);--bsg-seat-shadow:var(--ka-shadow-sm);
  --bsg-r-seat:var(--ka-r-3);
  position:fixed;inset:0;z-index:1250;display:flex;justify-content:center;background:var(--bsg-bg);color:var(--bsg-ink);font-family:var(--ka-font);font-size:var(--ka-fs-14);line-height:var(--ka-lh-1-4);-webkit-text-size-adjust:100%;overscroll-behavior:contain
}
html[data-theme="dark"] .bsg-root{--bsg-chip-s:42%;--bsg-chip-l:23%;--bsg-chip-ink-l:80%;--bsg-bus-fill:var(--ka-app-bg)}
.bsg-root *{box-sizing:border-box}
.bsg-root [hidden]{display:none!important}
.bsg-root button,.bsg-root input{font:inherit;color:inherit}
.bsg-root button{cursor:pointer;-webkit-tap-highlight-color:transparent}
.bsg-root :focus-visible{outline:calc(var(--ka-border-w) * 2) solid var(--bsg-accent);outline-offset:var(--ka-ring-offset)}
.bsg-root .bsg-ic{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}
.bsg-root .bsg-ic.sm{width:14px;height:14px}
.bsg-root .bsg-ic.xs{width:12px;height:12px}

/* Uygulama iskeleti */
.bsg-root .bsg-app{width:100%;height:100%;display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto auto minmax(0,1fr) auto auto;max-width:560px;background:var(--bsg-bg);padding-top:var(--ka-safe-top)}
.bsg-root .bsg-top{grid-row:1;display:flex;align-items:center;gap:var(--ka-sp-2);padding:var(--ka-sp-10) var(--ka-sp-8) var(--ka-sp-6) var(--ka-sp-6)}
.bsg-root .bsg-ttl{flex:1;min-width:0;padding-left:var(--ka-sp-4)}
.bsg-root .bsg-ttl h1{margin:0;font-size:var(--ka-fs-18);font-weight:var(--ka-fw-750);letter-spacing:var(--ka-ls-n015);line-height:var(--ka-lh-1-2)}
.bsg-root .bsg-ttl small{display:block;color:var(--bsg-muted);font-size:var(--ka-fs-12);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bsg-root .bsg-ibtn{width:42px;height:42px;display:grid;place-items:center;flex:none;padding:0;border:0;border-radius:var(--ka-r-3);background:transparent}
.bsg-root .bsg-ibtn:hover{background:var(--bsg-surface-2)}
.bsg-root .bsg-ibtn[disabled]{opacity:.32;cursor:default;background:transparent}
.bsg-root .bsg-btn{height:38px;padding:0 var(--ka-sp-14);display:inline-flex;align-items:center;justify-content:center;gap:var(--ka-sp-8);border:var(--ka-border-w) solid var(--bsg-line-strong);border-radius:var(--ka-r-3);background:var(--bsg-surface);color:var(--bsg-ink);font-weight:var(--ka-fw-650);font-size:var(--ka-fs-13-5);white-space:nowrap}
.bsg-root .bsg-btn:hover{border-color:var(--bsg-ink)}
.bsg-root .bsg-btn.bsg-pri{background:var(--ka-btn-primary-bg);border-color:var(--ka-btn-primary-edge);color:var(--ka-btn-primary-ink);text-shadow:var(--ka-btn-primary-ink-shadow);box-shadow:var(--ka-btn-primary-shadow);-webkit-backdrop-filter:var(--ka-btn-primary-filter);backdrop-filter:var(--ka-btn-primary-filter)}
.bsg-root .bsg-btn.bsg-pri:hover{background:var(--ka-btn-primary-bg-hover);border-color:var(--ka-btn-primary-edge)}
.bsg-root .bsg-btn.bsg-pri:active{transform:scale(var(--ka-btn-primary-press-scale))}
.bsg-root .bsg-btn.bsg-dng{color:var(--bsg-danger);border-color:var(--bsg-danger)}
.bsg-root .bsg-btn[disabled]{opacity:.45;cursor:default}
.bsg-root .bsg-savebtn{height:36px;margin-inline:var(--ka-sp-4) var(--ka-sp-2);padding:0 var(--ka-sp-14);flex:none}
.bsg-root .bsg-savebtn:not(.is-dirty){background:var(--bsg-surface);border-color:var(--bsg-line-strong);color:var(--bsg-muted);text-shadow:none;box-shadow:none;-webkit-backdrop-filter:none;backdrop-filter:none}

/* Durum şeridi */
.bsg-root .bsg-stats{grid-row:2;display:grid;gap:var(--ka-sp-10);padding:var(--ka-sp-6) var(--ka-sp-16) var(--ka-sp-10)}
.bsg-root .bsg-st-main{display:flex;align-items:flex-end;gap:var(--ka-sp-12)}
.bsg-root .bsg-st-num{font-size:var(--ka-fs-32);line-height:1;font-weight:var(--ka-fw-800);letter-spacing:var(--ka-ls-n025);font-variant-numeric:tabular-nums}
.bsg-root .bsg-st-num span{font-size:var(--ka-fs-18);font-weight:var(--ka-fw-600);color:var(--bsg-muted);letter-spacing:0}
.bsg-root .bsg-st-lbl{flex:1;min-width:0;padding-bottom:var(--ka-sp-3);color:var(--bsg-muted);font-size:var(--ka-fs-13)}
.bsg-root .bsg-bar{height:6px;border-radius:var(--ka-r-10);background:var(--bsg-surface-2);overflow:hidden}
.bsg-root .bsg-bar i{display:block;height:100%;border-radius:inherit;background:var(--ka-btn-primary-bg);transition:width var(--ka-dur-220)}
.bsg-root .bsg-legend{display:flex;flex-wrap:wrap;gap:var(--ka-sp-6) var(--ka-sp-16);color:var(--bsg-muted);font-size:var(--ka-fs-12-5)}
.bsg-root .bsg-legend span{display:inline-flex;align-items:center;gap:var(--ka-sp-6)}
.bsg-root .bsg-legend b{color:var(--bsg-ink);font-weight:var(--ka-fw-700);font-variant-numeric:tabular-nums}
.bsg-root .bsg-sw{width:13px;height:13px;border-radius:var(--ka-rs-4);border:calc(var(--ka-border-w) * 1.5) dashed var(--bsg-line-strong)}
.bsg-root .bsg-sw.bsg-res{border:calc(var(--ka-border-w) * 1.5) solid var(--bsg-line-strong);background:repeating-linear-gradient(135deg,var(--bsg-line-strong) 0 1.5px,transparent 1.5px 4.5px)}
.bsg-root .bsg-sw.bsg-bad{border:calc(var(--ka-border-w) * 1.5) solid var(--bsg-line-strong);background:linear-gradient(to top right,transparent calc(50% - 1px),var(--bsg-line-strong) 50%,transparent calc(50% + 1px)),linear-gradient(to bottom right,transparent calc(50% - 1px),var(--bsg-line-strong) 50%,transparent calc(50% + 1px))}
.bsg-root .bsg-warn{display:flex;align-items:center;gap:var(--ka-sp-8);margin:0;color:var(--bsg-danger);font-size:var(--ka-fs-12-5);font-weight:var(--ka-fw-600)}
.bsg-root .bsg-stats.bsg-compact{gap:var(--ka-sp-4);padding-bottom:var(--ka-sp-6)}
.bsg-root .bsg-stats.bsg-compact .bsg-st-num{font-size:var(--ka-fs-24)}
.bsg-root .bsg-stats.bsg-compact .bsg-st-num span{font-size:var(--ka-fs-15)}
.bsg-root .bsg-pickbar{grid-row:3;display:flex;align-items:center;gap:var(--ka-sp-10);margin:0 var(--ka-sp-16) var(--ka-sp-8);padding:var(--ka-sp-8) var(--ka-sp-8) var(--ka-sp-8) var(--ka-sp-12);border:var(--ka-border-w) solid var(--bsg-accent-line);border-radius:var(--ka-r-3);background:var(--bsg-accent-soft);font-size:var(--ka-fs-13)}
.bsg-root .bsg-pickbar p{flex:1;min-width:0;margin:0}
.bsg-root .bsg-pickbar .bsg-btn{height:32px;padding:0 var(--ka-sp-10);font-size:var(--ka-fs-12-5)}

/* Otobüs planı (hücre ızgarası) */
.bsg-root .bsg-planwrap{grid-row:4;min-height:0;overflow:auto;overscroll-behavior:contain;padding:var(--ka-sp-8) var(--ka-sp-16) var(--ka-sp-22);-webkit-overflow-scrolling:touch}
.bsg-root .bsg-zoomctl{position:sticky;top:0;z-index:6;height:0;display:flex;align-items:flex-start;justify-content:flex-end;overflow:visible}
.bsg-root .bsg-zoomctl div{display:inline-flex;margin-top:var(--ka-sp-2);border:var(--ka-border-w) solid var(--bsg-line-strong);border-radius:var(--ka-r-3);background:var(--bsg-surface);box-shadow:var(--bsg-seat-shadow)}
.bsg-root .bsg-zoomctl button{width:38px;height:36px;display:grid;place-items:center;padding:0;border:0;background:transparent}
.bsg-root .bsg-zoomctl button[disabled]{opacity:.35;cursor:default}
