.bsg-root .csg-wall{position:absolute;display:flex;align-items:center;justify-content:center;min-width:0;min-height:0;z-index:2;border-radius:var(--ka-rs-4);font-size:var(--ka-fs-10);font-weight:var(--ka-fw-700);line-height:1;pointer-events:none;-webkit-touch-callout:none}
