.bsg-root .csg-wall.is-top{top:3px}
.bsg-root .csg-wall.is-bottom{bottom:3px}
.bsg-root .csg-wall.is-left{left:3px}
.bsg-root .csg-wall.is-right{right:3px}
.bsg-root .csg-wl{display:block;max-width:100%;max-height:100%;overflow:hidden;padding:0 var(--ka-sp-4);text-overflow:ellipsis;white-space:nowrap}
.bsg-root .csg-wall.is-left .csg-wl,.bsg-root .csg-wall.is-right .csg-wl{writing-mode:vertical-rl;padding:var(--ka-sp-4) 0}
.bsg-root .csg-wall.is-left .csg-wl{transform:rotate(180deg)}
.bsg-root .csg-wall.k-board{background:var(--bsg-line-strong);color:var(--bsg-ink)}
