.bsg-root .csg-wall.k-window{border:calc(var(--ka-border-w) * 1.5) solid var(--bsg-line-strong);background:var(--bsg-surface-2);color:var(--bsg-muted)}
.bsg-root .csg-wall.is-sel{z-index:4;outline:calc(var(--ka-border-w) * 2) solid var(--bsg-accent);outline-offset:1px}
