.bsg-root .csg-wall.is-ghost{z-index:5;border:calc(var(--ka-border-w) * 2) dashed var(--bsg-accent);background:var(--bsg-accent-soft);color:transparent;opacity:.8;pointer-events:none}
.bsg-root .csg-wall.is-ghost.is-bad{border-color:var(--bsg-danger);background:var(--bsg-danger-soft)}
.bsg-root .csg-wrh{position:absolute;z-index:5;width:30px;height:30px;touch-action:none;pointer-events:auto}
