/* ===== A4 RAPORLAR — öğretmen profili ve öğrenci bilgi raporu (.pr-*) =====
   js/modules/people-reports.js çıktısının kağıt stili. Kağıt her zaman beyazdır; renkler --ka-report-people-* belirteçlerinden gelir.
   ReportEngine'in genel .ka-report th/td kuralları !important olduğundan burada da !important kullanılır. */
.ka-report .pr-doc .bolum-baslik{margin:var(--ka-report-people-gap) 0 1.5mm!important;padding:1.2mm 2.5mm!important;border-left-width:var(--ka-report-people-bar)!important;font-size:10pt!important;line-height:1.2!important}
.ka-report .pr-id{display:flex;align-items:center;gap:4mm;margin:0 0 3mm;padding:3mm 4mm;border:var(--ka-report-people-hair) solid var(--ka-report-people-line);border-left:var(--ka-report-people-bar) solid var(--ka-report-people-accent);background:var(--ka-report-people-soft);break-inside:avoid}
.ka-report .pr-id-mark{display:grid;place-items:center;flex:none;width:13mm;height:13mm;background:var(--ka-report-people-accent);color:var(--ka-report-people-on-accent);font-size:15pt;font-weight:800;letter-spacing:.02em}
.ka-report .pr-id-main{display:flex;flex-direction:column;gap:.8mm;min-width:0}
.ka-report .pr-id-main strong{color:var(--ka-report-people-ink);font-size:15pt;line-height:1.1}
.ka-report .pr-id-main span{color:var(--ka-report-people-muted);font-size:9pt;font-weight:700}
.ka-report .pr-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:0 0 3mm;border:var(--ka-report-people-hair) solid var(--ka-report-people-line);break-inside:avoid}
.ka-report .pr-kpis>div{display:flex;flex-direction:column;align-items:center;gap:.6mm;padding:2mm 1.5mm;text-align:center}
.ka-report .pr-kpis>div+div{border-left:var(--ka-report-people-hair) solid var(--ka-report-people-line)}
.ka-report .pr-kpis b{color:var(--ka-report-people-accent);font-size:15pt;line-height:1}
.ka-report .pr-kpis span{color:var(--ka-report-people-muted);font-size:7pt;font-weight:700}
.ka-report .pr-doc .bolum-baslik small,.ka-report .pr-sub small{margin-left:1.5mm;color:var(--ka-report-people-muted);font-size:7.5pt;font-weight:700}
.ka-report .pr-sub{margin:3mm 0 1.5mm;color:var(--ka-report-people-ink);font-size:9pt;font-weight:800}
.ka-report .pr-dl th{width:19%;background:var(--ka-report-people-soft)!important;border:var(--ka-report-people-hair) solid var(--ka-report-people-rule)!important;color:var(--ka-report-people-ink)!important;font-weight:800!important;text-align:left!important}
.ka-report .pr-dl td{width:31%;text-align:left!important}
.ka-report .pr-empty{margin:1mm 0 2mm;padding:2mm 3mm;border:var(--ka-report-people-hair) dashed var(--ka-report-people-line);color:var(--ka-report-people-muted);font-size:8pt}
.ka-report .pr-note{margin:1.5mm 0 0;color:var(--ka-report-people-muted);font-size:7.5pt;line-height:1.35}
.ka-report .pr-tt{table-layout:fixed}
.ka-report .pr-tt .pr-tt-h{width:9mm;background:var(--ka-report-people-soft)!important;color:var(--ka-report-people-ink)!important}
.ka-report .pr-tt td{height:9mm;text-align:center!important}
.ka-report .pr-tt .pr-tt-c{background:var(--ka-report-people-cell)!important}
.ka-report .pr-tt .pr-tt-0{background:var(--ka-report-bg)!important}
.ka-report .pr-tt .pr-tt-c b,.ka-report .pr-tt .pr-tt-c span{display:block;line-height:1.15}
.ka-report .pr-tt .pr-tt-c b{color:var(--ka-report-people-ink);font-size:8pt}
.ka-report .pr-tt .pr-tt-c span{color:var(--ka-report-people-muted);font-size:6.5pt}
.ka-report .pr-checks td{text-align:center!important}
.ka-report .pr-checks td:first-child,.ka-report .pr-left{text-align:left!important}
.ka-report .pr-ck{color:var(--ka-report-people-muted);font-size:9pt}
.ka-report .pr-ck.is-on{color:var(--ka-report-people-accent);font-weight:800}
.ka-report .pr-diff{font-weight:800}
.ka-report .pr-diff.is-over{color:var(--ka-report-people-over)}
.ka-report .pr-diff.is-under{color:var(--ka-report-people-under)}
.ka-report .pr-diff.is-ok{color:var(--ka-report-people-accent)}
.ka-report .pr-chart{margin:2mm 0 0;break-inside:avoid}
.ka-report .pr-trend{display:block;width:100%;max-height:50mm}
.ka-report .pr-trend-grid{stroke:var(--ka-report-people-rule);stroke-width:.6}
.ka-report .pr-trend-axis{fill:var(--ka-report-people-muted);font-size:7px}
.ka-report .pr-trend-line{fill:none;stroke:var(--ka-report-people-accent);stroke-width:1.6;stroke-linejoin:round}
.ka-report .pr-trend-dot{fill:var(--ka-report-bg);stroke:var(--ka-report-people-accent);stroke-width:1.6}
.ka-report .pr-trend-val{fill:var(--ka-report-people-ink);font-size:7px;font-weight:700}

