html .ka-web-crumb__group{font-size:var(--ka-fs-14);font-weight:var(--ka-fw-650);color:var(--ka-text-muted);white-space:nowrap}
html .ka-web-crumb__sep{display:grid;place-items:center;color:var(--ka-text-muted)}
