html .ka-web-crumb__title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:var(--ka-fs-17);line-height:var(--ka-lh-1-2);font-weight:var(--ka-fw-850);letter-spacing:var(--ka-ls-n01);color:var(--gl-fg)}
html .ka-web-search{
  align-items:center;gap:var(--ka-sp-10);flex:1 1 280px;max-width:560px;min-width:var(--ka-ic-120);height:calc(44px + var(--ka-btn-grow));margin:0;padding:0 var(--ka-sp-14);
  border:var(--ka-border-w) solid var(--gl-edge);border-radius:var(--ka-r-4);background:var(--gl-field);color:var(--ka-text-muted);cursor:text;
  transition:border-color var(--ka-dur-150) var(--ka-ease-1),box-shadow var(--ka-dur-150) var(--ka-ease-1);
}
html .ka-web-search svg{flex:none;width:var(--ka-ic-18);height:var(--ka-ic-18)}
html .ka-web-search>input.ka-field-bare{flex:1 1 auto;min-width:0;width:auto;height:100%;min-height:0;margin:0;padding:0;border:0;border-radius:0;outline:0;background:transparent;box-shadow:none;font:inherit;font-size:var(--ka-fs-14);font-weight:var(--ka-fw-600);color:var(--gl-fg);-webkit-appearance:none;appearance:none}
html .ka-web-search input::-webkit-search-cancel-button{display:none}
html .ka-web-search input::placeholder{color:var(--ka-text-muted);opacity:1}
html .ka-web-search kbd{flex:none;padding:var(--ka-sp-2) var(--ka-sp-7);border:var(--ka-border-w) solid var(--gl-edge);border-radius:var(--ka-r-1);font-family:var(--ka-font-mono);font-size:var(--ka-fs-11);font-weight:var(--ka-fw-700);color:var(--ka-text-muted)}
html .ka-web-search:focus-within{border-color:rgba(var(--t-accent-rgb),.6);box-shadow:0 0 0 calc(var(--ka-border-w) * 3) rgba(var(--t-accent-rgb),.2)}
html .ka-web-search:focus-within kbd{display:none}
