}
@media(min-width:1100px) and (max-height:760px){html .ka-web-recent{display:none}}

/* ===== GEZİNME SAYFALARI =====
   js/core/nav-pages.js (Araçlar / Yönetim, araç grubu, Okul, İletişim, Programım, Ben)
   ile web yan menüsü (js/core/web-shell.js) için TEK yetkili tanım. Yalnız tema belirteçleri kullanılır:
   renkler --gl-* / --ka-* / --c-* paletinden, ölçüler --ka-sp-* / --ka-fs-* / --ka-r-* / --ka-ic-* basamaklarından gelir.
   Satırın / çipin / ikon kutusunun rengi işaretlemedeki data-tone değerinden (aşağıdaki ton sistemi) türetilir. */

/* — ton sistemi: data-tone → --mc-rgb → --mc-t (zemin) · --mc-b (çizgi) · --mc-ink (yazı / ikon) — */
html :is(.ka-nav-page,.ka-web-side){--mc-rgb:var(--t-accent-rgb)}
html :is(.ka-nav-page,.ka-web-side),
html :is(.ka-nav-page,.ka-web-side) [data-tone]{
  --mc:rgb(var(--mc-rgb));
  --mc-t:color-mix(in srgb,var(--mc) 16%,transparent);--mc-b:color-mix(in srgb,var(--mc) 34%,transparent);
  --mc-ink:color-mix(in srgb,var(--mc) var(--gl-ink-pct),var(--gl-ink-mix));
}
html :is(.ka-nav-page) [data-tone="indigo"]{--mc-rgb:var(--c-indigo)}
html :is(.ka-nav-page) [data-tone="blue"]{--mc-rgb:var(--c-blue)}
html :is(.ka-nav-page) [data-tone="sky"]{--mc-rgb:var(--c-sky)}
html :is(.ka-nav-page) [data-tone="cyan"]{--mc-rgb:var(--c-cyan)}
html :is(.ka-nav-page) [data-tone="teal"]{--mc-rgb:var(--c-teal)}
html :is(.ka-nav-page) [data-tone="green"]{--mc-rgb:var(--c-emerald)}
html :is(.ka-nav-page) [data-tone="amber"]{--mc-rgb:var(--c-amber)}
html :is(.ka-nav-page) [data-tone="orange"]{--mc-rgb:var(--c-orange)}
html :is(.ka-nav-page) [data-tone="red"]{--mc-rgb:var(--c-red)}
html :is(.ka-nav-page) [data-tone="rose"]{--mc-rgb:var(--c-rose)}
html :is(.ka-nav-page) [data-tone="pink"]{--mc-rgb:var(--c-pink)}
html :is(.ka-nav-page) [data-tone="violet"],
html :is(.ka-nav-page) [data-tone="purple"]{--mc-rgb:var(--c-violet)}
html :is(.ka-nav-page) [data-tone="slate"]{--mc-rgb:var(--c-slate)}

/* — ortak kart yüzeyi — */
html #v2ModuleRoot :is(.ka-nav-rowcard,.ka-nav-gtile,.ka-nav-switch,.ka-nav-profile,.ka-nav-cal,.ka-nav-lessons,.ka-nav-lesson.is-off,.ka-nav-day,.ka-nav-fav){
  position:relative;min-width:0;color:var(--gl-fg);
  background:var(--gl-bg);border:var(--ka-card-border-w) solid var(--gl-edge);border-radius:var(--ka-card-radius);box-shadow:var(--gl-shadow);
  -webkit-backdrop-filter:var(--gl-blur);backdrop-filter:var(--gl-blur);
}
html #v2ModuleRoot :is(.ka-nav-gtile,.ka-nav-switch,.ka-nav-day,.ka-nav-fav){
  appearance:none;margin:0;font:inherit;cursor:pointer;text-align:left;
  transition:transform var(--ka-dur-150) var(--ka-ease-1),border-color var(--ka-dur-150) var(--ka-ease-1),background var(--ka-dur-150) var(--ka-ease-1);
}
@media(hover:hover){
  html #v2ModuleRoot :is(.ka-nav-gtile,.ka-nav-switch,.ka-nav-fav):hover{border-color:rgba(var(--t-accent-rgb),.45)}
}
html #v2ModuleRoot :is(.ka-nav-gtile,.ka-nav-switch,.ka-nav-day,.ka-nav-fav):active{transform:scale(.985)}
html #v2ModuleRoot :is(.ka-nav-page) :is(button,[role="button"],input):focus-visible{outline:var(--ka-ring-w) solid var(--ka-focus);outline-offset:var(--ka-ring-offset)}

/* ── araç simgeleri (.ka-glyph): eski menüdeki emoji; bilinen emoji aşağıda çizgi simgeye (mask --ic) çevrilir, js/core/app-nav.js markGlyphs() maskelenenlere .has-ic verir, bilinmeyenler emoji kalır ── */
html .ka-glyph{position:relative;width:100%;height:100%;display:grid;place-items:center;font-style:normal;font-size:var(--ka-fs-20);line-height:1}
