@media(min-width:1100px){html .ka-web-ico--sub .ka-glyph{font-size:var(--ka-fs-14)}}
html .ka-glyph.has-ic{font-size:0}
html .ka-glyph.has-ic::before{content:"";position:absolute;inset:22%;background:currentColor;-webkit-mask:var(--ic,none) center/contain no-repeat;mask:var(--ic,none) center/contain no-repeat}
html .ka-nav-ico .ka-glyph.has-ic::before{background:var(--mc-ink)}
