/* ===== SAYFA ÇATISI (.ka-nav-page) ===== */
html #v2ModuleRoot .ka-nav-page{width:100%;max-width:760px;margin:0 auto;display:flex;flex-direction:column;gap:var(--ka-sp-14);color:var(--gl-fg)}
html #v2ModuleRoot .ka-nav-page [hidden]{display:none!important}
html #v2ModuleRoot .ka-nav-page .ka-nav-head{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--ka-sp-12);padding:var(--ka-sp-2) var(--ka-sp-2) 0}
html #v2ModuleRoot .ka-nav-page .ka-nav-head h2{margin:0;font-size:var(--ka-fs-24);line-height:var(--ka-lh-1-15);font-weight:var(--ka-fw-900);letter-spacing:var(--ka-ls-n02);color:var(--gl-fg)}
html #v2ModuleRoot .ka-nav-page .ka-nav-head p{margin:var(--ka-sp-4) 0 0;font-size:var(--ka-fs-13);line-height:var(--ka-lh-1-35);color:var(--ka-text-muted)}
html #v2ModuleRoot .ka-nav-page .ka-nav-stack{display:flex;flex-direction:column;gap:var(--ka-sp-14)}
html #v2ModuleRoot .ka-nav-page .ka-nav-hint{margin:0 var(--ka-sp-4);font-size:var(--ka-fs-12);line-height:var(--ka-lh-1-45);color:var(--ka-text-muted)}
html #v2ModuleRoot .ka-nav-page .ka-nav-note{display:flex;align-items:flex-start;gap:var(--ka-sp-10);padding:var(--ka-sp-12) var(--ka-sp-14);border:var(--ka-border-w) solid var(--gl-edge);border-radius:var(--ka-card-radius-sm);background:var(--gl-field);font-size:var(--ka-fs-13);line-height:var(--ka-lh-1-45);color:var(--gl-fg)}
html #v2ModuleRoot .ka-nav-page .ka-nav-note>svg{flex:none;color:rgb(var(--c-emerald))}

/* arama kutusu */
html #v2ModuleRoot .ka-nav-page .ka-nav-search{display:flex;align-items:center;gap:var(--ka-sp-10);min-height:calc(48px + var(--ka-field-grow));padding:0 var(--ka-sp-14);border:var(--ka-field-border-w) solid var(--gl-edge);border-radius:var(--ka-r-5);background:var(--gl-bg);color:var(--ka-text-muted);transition:border-color var(--ka-dur-150),box-shadow var(--ka-dur-150)}
html #v2ModuleRoot .ka-nav-page .ka-nav-search>svg{flex:none}
html #v2ModuleRoot .ka-nav-page .ka-nav-search>input.ka-field-bare{flex:1 1 auto;min-width:0;width:auto;height:100%;min-height:0;margin:0;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;color:var(--gl-fg);font:inherit;font-size:var(--ka-fs-15);outline:0}
html #v2ModuleRoot .ka-nav-page .ka-nav-search>input::placeholder{color:var(--ka-text-muted);opacity:1}
html #v2ModuleRoot .ka-nav-page .ka-nav-search>input::-webkit-search-cancel-button{display:none}
html #v2ModuleRoot .ka-nav-page .ka-nav-search:focus-within{border-color:rgba(var(--t-accent-rgb),.6);box-shadow:0 0 0 calc(var(--ka-border-w) * 3) rgba(var(--t-accent-rgb),.2)}

/* bölüm + başlık */
html #v2ModuleRoot .ka-nav-page .ka-nav-section{display:flex;flex-direction:column;gap:var(--ka-sp-8)}
html #v2ModuleRoot .ka-nav-page .ka-nav-section>h3{display:flex;align-items:center;gap:var(--ka-sp-8);margin:0 var(--ka-sp-2);font-size:var(--ka-fs-13);line-height:var(--ka-lh-1-22);font-weight:var(--ka-fw-800);letter-spacing:var(--ka-ls-02);color:var(--ka-text-muted)}
html #v2ModuleRoot .ka-nav-page .ka-nav-section>h3>span{min-width:var(--ka-ic-20);height:var(--ka-ic-20);padding:0 var(--ka-sp-6);display:grid;place-items:center;border-radius:var(--ka-radius-pill);background:var(--gl-field);font-size:var(--ka-fs-11);font-weight:var(--ka-fw-800);color:var(--ka-text-muted)}
html #v2ModuleRoot .ka-nav-page .ka-nav-section--split{padding-top:var(--ka-sp-6)}

/* ikon kutusu · rozet · ok */
html #v2ModuleRoot .ka-nav-page .ka-nav-ico{flex:none;width:var(--ka-ic-40);height:var(--ka-ic-40);display:grid;place-items:center;border-radius:var(--ka-r-3);background:var(--mc-t);border:var(--ka-border-w) solid var(--mc-b);color:var(--mc-ink)}
html #v2ModuleRoot .ka-nav-page .ka-nav-ico[data-size="30"]{width:var(--ka-ic-30);height:var(--ka-ic-30)}
html #v2ModuleRoot .ka-nav-page .ka-nav-ico[data-size="32"]{width:var(--ka-ic-32);height:var(--ka-ic-32)}
html #v2ModuleRoot .ka-nav-page .ka-nav-ico[data-size="46"]{width:var(--ka-ic-46);height:var(--ka-ic-46)}
html #v2ModuleRoot .ka-nav-page .ka-nav-pill{display:inline-flex;align-items:center;flex:none;min-height:var(--ka-sp-22);padding:0 var(--ka-sp-9);border-radius:var(--ka-radius-pill);background:var(--mc-t);border:var(--ka-border-w) solid var(--mc-b);font-size:var(--ka-fs-11);font-weight:var(--ka-fw-800);line-height:1;white-space:nowrap;color:var(--mc-ink)}
html #v2ModuleRoot .ka-nav-page .ka-nav-chev{flex:none;display:grid;place-items:center;color:var(--ka-text-muted)}

/* sık kullandıklarım */
html #v2ModuleRoot .ka-nav-page .ka-nav-favs{display:flex;gap:var(--ka-sp-8);margin:0 calc(var(--ka-sp-4) * -1);padding:var(--ka-sp-2) var(--ka-sp-4) var(--ka-sp-4);overflow-x:auto;scrollbar-width:none}
html #v2ModuleRoot .ka-nav-page .ka-nav-favs::-webkit-scrollbar{display:none}
html #v2ModuleRoot .ka-nav-page .ka-nav-fav{flex:none;display:inline-flex;align-items:center;gap:var(--ka-sp-8);min-height:calc(44px + var(--ka-btn-grow));padding:0 var(--ka-sp-14) 0 var(--ka-sp-6);border-radius:var(--ka-radius-pill);font-size:var(--ka-fs-13);font-weight:var(--ka-fw-750);white-space:nowrap}

/* araç grupları — öğretmen: iki sütun kart · idareci: büyük satır */
html #v2ModuleRoot .ka-nav-page .ka-nav-gtiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--ka-sp-10)}
html #v2ModuleRoot .ka-nav-page .ka-nav-gtile{display:flex;align-items:center;gap:var(--ka-sp-10);min-height:calc(68px + var(--ka-row-grow));padding:var(--ka-sp-12)}
html #v2ModuleRoot .ka-nav-page .ka-nav-gtile__copy{min-width:0;display:flex;flex-direction:column;gap:var(--ka-sp-2)}
html #v2ModuleRoot .ka-nav-page .ka-nav-gtile__copy strong{font-size:var(--ka-fs-14);line-height:var(--ka-lh-1-22);font-weight:var(--ka-fw-800);overflow-wrap:anywhere}
html #v2ModuleRoot .ka-nav-page .ka-nav-gtile__copy small{font-size:var(--ka-fs-12);color:var(--ka-text-muted)}
/* idareci araçları: kategori bölümleri ve araç kartları (kategori adı · kart ızgarası) */

/* araç listesi (grup sayfası · arama sonuçları · İletişim · Ben) */
html #v2ModuleRoot .ka-nav-page .ka-nav-rowcard{overflow:hidden;padding:0}
html #v2ModuleRoot .ka-nav-page .ka-nav-row{display:flex;align-items:center;width:100%;min-height:calc(60px + var(--ka-row-grow))}
html #v2ModuleRoot .ka-nav-page .ka-nav-rowcard>.ka-nav-row+.ka-nav-row{border-top:var(--ka-border-w) solid var(--gl-sep)}
html #v2ModuleRoot .ka-nav-page .ka-nav-row__main{appearance:none;flex:1 1 auto;min-width:0;display:flex;align-items:center;gap:var(--ka-sp-12);margin:0;padding:var(--ka-sp-10) var(--ka-sp-14);border:0;border-radius:0;background:transparent;box-shadow:none;color:inherit;font:inherit;text-align:left;cursor:pointer;transition:background var(--ka-dur-150) var(--ka-ease-1)}
html #v2ModuleRoot .ka-nav-page .ka-nav-row__main:hover,html #v2ModuleRoot .ka-nav-page .ka-nav-row__main:active{background:var(--gl-field)}
